import {gameConfig} from "../../config";
import {getDefaultPlayerData} from "../../config.default";
import {shopConfig} from "../../config.shop";
import {addShopItemToState} from "../../logic";
import {GameService} from "./GameService";
import type {ServiceConfig} from "./types";

export interface IGameServiceProviderOptions {
    /** опциональный логгинг в консоль **/
    isLogging?: boolean;
    /** опциональный key для сохранения данных **/
    playerDataKey?: string;
    /** моковые флаги для сторибука **/
    isMockShop?: boolean;
    isMockAd?: boolean;
}

export class GameServiceProvider {
    private static gameService?: GameService;

    /** Получить инстанс, предварительно нужно вызвать reset с валидными опциями */
    static get(): GameService {
        if (this.gameService == null) {
            throw new Error("GameServiceProvider not initialized. Call reset() first.");
        }
        return this.gameService;
    }

    static reset(options?: IGameServiceProviderOptions): GameService {
        this.gameService = new GameService({
            ...options,
            serviceConfig: createServiceConfig(),
        });
        return this.gameService;
    }

    /** вернуть временный сервис с настройками **/
    static getTempService(options?: IGameServiceProviderOptions): GameService {
        return new GameService({
            ...options,
            serviceConfig: createServiceConfig(),
        });
    }
}


/** Собирает внутренний конфиг сервисного слоя из root-конфигов приложения. */
function createServiceConfig(): ServiceConfig {
    return {
        gameId: gameConfig.gameId,
        commonAdCooldownMs: gameConfig.ads.cooldowns.commonMs,
        rewardAdCooldownMs: gameConfig.ads.cooldowns.rewardMs,
        saveDebounceMs: gameConfig.dataServiceOptions.saveDebounceMs,
        getDefaultPlayerData,
        shopConfig,
        addShopItemToState,
    };
}
