import {SceneEvents} from "../../../../common";
import {GamePlayCardTheme} from "../../../../logic";
import {GameServiceProvider} from "../../../../services";
import {IGameEvents} from "../../../events";

interface IProps {
    scene: Phaser.Scene;
}

/** Контроллер темы карт: сохраняет выбор и сообщает активной сцене, что карты надо перерисовать. **/
export class CardThemeController {
    private readonly events: SceneEvents<IGameEvents>;

    constructor(private readonly props: IProps) {
        this.events = new SceneEvents<IGameEvents>({scene: props.scene});
    }

    destroy(): void {
        this.events.unSubscribeAll();
    }

    getSelectedTheme(): GamePlayCardTheme {
        return GameServiceProvider.get().playerData.get().cardsTheme;
    }

    selectCardsTheme(cardsTheme: GamePlayCardTheme): void {
        const gameService = GameServiceProvider.get();

        gameService.playerData.set({
            /** Flow только просит контроллер сменить тему; сохранение остается здесь. **/
            cardsTheme,
        });

        this.events.emit("cardThemeFaceChange", {
            faceAssetName: cardsTheme,
        });
    }
}
