import type {IShopConfig} from "../types";

/** Проверяет id rewarded-награды по переданному конфигу магазина. */
export function isRewardPurchaseId(shopConfig: IShopConfig, value: unknown): boolean {
  return typeof value === "string" && shopConfig.shopItemsOrdered.rewardItemIds.includes(value);
}

/** Проверяет id in-app покупки по переданному конфигу магазина. */
export function isInAppPurchaseId(shopConfig: IShopConfig, value: unknown): boolean {
  return typeof value === "string" && shopConfig.shopItemsOrdered.buyItemIds.includes(value);
}
