import {SceneEvents} from "../../../../common";
import {GameServiceProvider} from "../../../../services";
import {IGameEvents} from "../../../events";

interface IProps {
    scene: Phaser.Scene;
}

/** Контроллер рубашек: выбор и синхронизация события с игровыми картами. **/
export class CardBackShopController {
    private readonly events: SceneEvents<IGameEvents>;

    constructor(private readonly props: IProps) {
        this.events = new SceneEvents<IGameEvents>({scene: props.scene});
    }

    destroy(): void {
        this.events.unSubscribeAll();
    }

    selectCardBack(cardBackAssetName: string): void {
        const gameService = GameServiceProvider.get();

        gameService.playerData.set({
            cardBackAssetName,
        });

        this.events.emit("cardThemeBackChange", {
            backAssetKey: cardBackAssetName,
        });
    }
}
