import { makeAlign } from "@kvisaz/phaser-sugar";
import { ButtonChild, ContainerButton } from "../../common/game-core";

interface IProps {
  scene: Phaser.Scene;
  name?: string;
  onClick: () => void;
  onHover?: () => void;
  buttonImageBuilder: () => ButtonChild;
  rewardIconBuilder: () => Phaser.GameObjects.Image;
  initAmount?: number;
  textBuilder: (text: string) => Phaser.GameObjects.Text;
  textBgBuilder: (w: number, h: number) => Phaser.GameObjects.NineSlice;
}

const BADGE_NINE_PADDING = 13;
const ASSETS_VIEW_ATLAS_URL = "./assets/atlases/assets-views.png";
const BADGE_FRAME_NAME = "consumable.nine.13.png";
const REWARD_ICON_FRAME_NAME = "iconplay22x22.png";

/**
 * Универсальная кнопка с указателем какого-то числа amount
 * дизайн по умолчанию - число справа
 **/
export class ConsumableButton extends ContainerButton {
  protected amount: number;
  protected isRewardEnabled: boolean;
  protected content: ButtonContent;

  constructor(props: IProps) {
    const content = createContentGameObjects(props);
    super({
      gameObjects: [content.textBg, content.text, content.icon, content.rewardIcon],
      onClick: props.onClick,
      onOver: props.onHover,
      options: {
        once: false,
        onDisabled: () => {
          setButtonIconEnabled(content.icon, false);
          this.updateEnableText();
        },
        onEnabled: () => {
          setButtonIconEnabled(content.icon, true);
          this.updateEnableText();
        },
        disableAfterClick: {
          ms: 0,
        },
      },
    });
    this.content = content;
    this.name = props.name ?? "consumableButton";
    this.isRewardEnabled = false;
    this.amount = Math.max(0, props.initAmount ?? 0);
    this.layout();
    this.updateInteractiveZone();
  }

  layout() {
    const { text, textBg, icon, rewardIcon } = this.content;
    const { isRewardEnabled, amount } = this;
    const isRewardActive = isRewardEnabled && amount === 0;

    makeAlign((align) => {
      align.anchor(icon).bottomTo(textBg);
      align.anchor(icon).centerX(textBg);
      align.anchor(textBg).center(text);
      align.anchor(textBg).center(rewardIcon);
    });

    rewardIcon.setVisible(isRewardActive);
    text.setVisible(!isRewardActive);

    const { width, height } = this.getBounds();
    this.setSize(width, height);
    this.input?.hitArea?.setSize(width, height);
  }

  setAmount(amount: number) {
    if (this.scene == null) return;
    this.amount = Math.max(0, amount);
    this.content.text.setText(`${this.amount}`);
    this.layout();
  }

  incAmount(inc: number) {
    this.setAmount(this.amount + inc);
  }

  protected updateEnableText() {
    const alpha = this.isEnabled ? 1 : 0.35;
    this.content.textBg.setAlpha(alpha);
    this.content.text.setAlpha(alpha);
  }

  /** todo test stories **/
  rewardIconEnable(enabled: boolean) {
    this.isRewardEnabled = enabled;
    this.layout();
  }
}

function createContentGameObjects(props: IProps): ButtonContent {
  const textBg = createAmountBadge(props.scene);
  const text = props.textBuilder(`${props.initAmount ?? 0}`);
  const icon = props.buttonImageBuilder();
  const rewardIcon = createRewardIcon(props.scene);

  return {
    icon,
    textBg,
    text,
    rewardIcon
  };
}

/** Создает нижний бейдж количества на тех же ассетах, что tuned buttonConsumable. **/
function createAmountBadge(scene: Phaser.Scene): Phaser.GameObjects.NineSlice {
  return new Phaser.GameObjects.NineSlice(
    scene,
    0,
    0,
    ASSETS_VIEW_ATLAS_URL,
    BADGE_FRAME_NAME,
    88,
    26,
    BADGE_NINE_PADDING,
    BADGE_NINE_PADDING,
    BADGE_NINE_PADDING,
    BADGE_NINE_PADDING,
  );
}

/** Создает play-иконку нулевого баланса на тех же ассетах, что tuned buttonConsumable. **/
function createRewardIcon(scene: Phaser.Scene): Phaser.GameObjects.Image {
  return new Phaser.GameObjects.Image(
    scene,
    0,
    0,
    ASSETS_VIEW_ATLAS_URL,
    REWARD_ICON_FRAME_NAME,
  );
}


type ButtonContent =  {
  icon: ButtonChild;
  rewardIcon: Phaser.GameObjects.Image;
  textBg: Phaser.GameObjects.NineSlice;
  text: Phaser.GameObjects.Text;
}

function setButtonIconEnabled(icon: ButtonChild, enabled: boolean): void {
  /**
   * Иконка может быть не Phaser.Image, а составным ButtonChild.
   * Tint применяем только когда объект его поддерживает; иначе мягко гасим alpha.
   */
  const tintableIcon = icon as ButtonChild & {
    setTint?: (value: number) => void;
    clearTint?: () => void;
  };

  if (typeof tintableIcon.setTint === "function" && typeof tintableIcon.clearTint === "function") {
    if (enabled) {
      tintableIcon.clearTint();
      return;
    }

    tintableIcon.setTint(0xa0a0a0);
    return;
  }

  if ("setAlpha" in icon && typeof icon.setAlpha === "function") {
    icon.setAlpha(enabled ? 1 : 0.55);
  }
}
